import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 newTimestamp, uint256 newBlockNumber) public {
        // Restrict to valid call: msg.value == 10 ether, and block.timestamp > pastBlockTime.
        vm.assume(amount == 10 ether);
        uint256 pastTime = c.pastBlockTime();
        vm.assume(newTimestamp > pastTime);
