pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2) public {
        timestamp1 = bound(timestamp1, 1, 1000000);
        timestamp2 = bound(timestamp2, 1, 1000000);
        // Ensure first call succeeds: block.timestamp > initial pastBlockTime (0)
        vm.warp(timestamp1);
        vm.deal(address(this), 10 ether);
        (bool success1,) = address(c).call{value: 10 ether}("");
        vm.assume(success1);
        uint256 pastAfterFirst = c.pastBlockTime();

        // Second call at same timestamp, ensure it would satisfy require(block.timestamp > pastBlockTime)
        vm.assume(timestamp2 > pastAfterFirst);
        vm.warp(timestamp2);
        vm.deal(address(this), 10 ether);
        (bool success2,) = address(c).call{value: 10 ether}("");
        vm.assume(success2);

        // Rule: If both calls succeeded and timestamp2 equals timestamp1, then pastBlockTime after second call must be > timestamp1
        // The mutant sets pastBlockTime = block.timestamp, so if timestamp2 == timestamp1, pastBlockTime would equal timestamp1, breaking the invariant.
        assertTrue(c.pastBlockTime() > timestamp1 || timestamp2 != timestamp1);
    }
}

