import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockOffset, uint256 value) public {
        // Ensure block.timestamp can vary; use vm.warp to set a specific timestamp
        // Assume value is exactly 10 ether to trigger the fallback logic
        vm.assume(value == 10 ether);

        // Record the current pastBlockTime before the call
        uint256 before = c.pastBlockTime();

        // Warp to a timestamp after the recorded pastBlockTime (or equal for mutant)
        uint256 newTime = bound(blockOffset, before, before + 1000);
        vm.warp(newTime);

        // Make the fallback call with exactly 10 ether
        (bool success, ) = address(c).call{value: value}("");

        // General rule: if the call succeeded, pastBlockTime must be > before (strictly)
        // For the reference, it succeeds only if block.timestamp > pastBlockTime, so newTime > before
        // For the mutant, it could succeed when newTime == before, making pastBlockTime = block.timestamp + 1 == newTime + 1, but then newTime == before, not > before
        // The careful rule: after a successful call, pastBlockTime > before
        if (success) {
            assertTrue(c.pastBlockTime() > before);
        } else {
            // If the call reverts (e.g., because block.timestamp <= pastBlockTime), pastBlockTime remains unchanged
            assertTrue(c.pastBlockTime() == before);
        }
    }
}

