pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp1, uint256 timestamp2) public {
        // bound both timestamps to a reasonable range (avoid overflow of block.timestamp)
        timestamp1 = bound(timestamp1, 1, type(uint40).max);
        timestamp2 = bound(timestamp2, 1, type(uint40).max);

        // Ensure timestamp2 >= timestamp1 so that the second call might succeed with >= but revert with >
        vm.assume(timestamp2 >= timestamp1);

        // First call at timestamp1
        vm.warp(timestamp1);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Second call at timestamp2 (which may equal timestamp1)
        vm.warp(timestamp2);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // Rule: If the second call's timestamp equals the first timestamp, then the second call must revert.
        // This is because the reference requires strict greater, so when timestamps are equal it should revert.
        // But note: due to pastBlockTime being set to timestamp1 + 1, even timestamp2 == timestamp1 might not revert
        // if the first call succeeded (pastBlockTime = timestamp1 + 1 > timestamp1), so the second call with timestamp2 == timestamp1
        // would see block.timestamp < pastBlockTime and revert. For timestamp2 == timestamp1 this holds unconditionally.
        if (timestamp1 == timestamp2) {
            assertTrue(!success2, "Second call at same timestamp should revert");
        } else {
            // If timestamps differ, we only enforce that the first call succeeded (timestamps > 0) and second call behavior
            // depends on the mutant. But the key invariant is the equality case.
            assertTrue(success1, "First call should succeed");
        }
    }
}

