            } else {
                // No transfer happens, balance increases by 10 ether
                assertTrue(balanceAfter == balanceBefore + 10 ether, "Balance should increase by 10 ether");
            }
        } else {
            // If call reverted (e.g., due to timestamp condition), balance unchanged
            assertTrue(address(c).balance == balanceBefore, "Balance unchanged on revert");
